CustomField.formula:
if ( isblank(Wednesday_Time_In__c) && isblank (Wednesday_Time_Out__c), 0,

if ( isblank(Wednesday_Lunch_End__c) && isblank(Wednesday_Lunch_Start__c),

( 

(floor(Wednesday_Time_Out_Proxy__c) + (Wednesday_Time_Out_Proxy__c- floor(Wednesday_Time_Out_Proxy__c))/60*100)

- (floor(Wednesday_Time_In_Proxy__c) + (Wednesday_Time_In_Proxy__c- floor(Wednesday_Time_In_Proxy__c))/60*100)

),

( 

(floor(Wednesday_Lunch_Start_Proxy__c ) + (Wednesday_Lunch_Start_Proxy__c- floor(Wednesday_Lunch_Start_Proxy__c))/60*100)

- (floor(Wednesday_Time_In_Proxy__c) + (Wednesday_Time_In_Proxy__c- floor(Wednesday_Time_In_Proxy__c))/60*100)

)

))
